{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f6f8f9;--accent:#3a6b6b;--muted:#6b7377;--card:#ffffff;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#213237;background:linear-gradient(180deg,var(--bg),#fff);}
    body{background-image:url('assets/img/pattern.svg');background-repeat:repeat;background-size:220px 220px;}
    .site{max-width:980px;margin:36px auto;padding:28px;background:var(--card);box-shadow:0 6px 28px rgba(23,31,35,0.06);border-radius:12px}
    header{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}
    .brand{display:flex;flex-direction:column}
    .brand h1{font-size:18px;margin:0;color:var(--accent)}
    .brand p{margin:2px 0 0;font-size:13px;color:var(--muted)}
    nav a{margin-left:12px;color:var(--accent);text-decoration:none;font-size:14px}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:22px;align-items:start}
    .panel{padding:18px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.8),var(--glass));}
    .intro{font-size:15px;color:#1f2b2b;line-height:1.45}
    .bio p{margin:0 0 10px}
    .muted{color:var(--muted);font-size:13px}
    .cta{display:inline-block;margin-top:12px;background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none}
    .details{font-size:13px;color:var(--muted);margin-top:10px}
    footer{margin-top:18px;font-size:13px;color:var(--muted)}
    .fineprint{background:#fbfbfb;border-left:3px solid #e1e6e6;padding:12px;border-radius:6px;margin-top:14px;font-size:13px}
  </style>
</head>
<body>
  <div class="site">
    <header>
      <div class="brand">
        <h1>{{BUSINESS_NAME}}</h1>
        <p>{{TAGLINE}}</p>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="about.html">About</a>
        <a href="specialties.html">Focus</a>
        <a href="approach.html">My Approach</a>
        <a href="fees.html">Fees</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main>
      <div class="hero">
        <section class="panel">
          <h2 style="margin-top:0">A brief note from your clinician</h2>
          <div class="intro bio">
            <p>I work with adults who are looking to build steadier ways of managing stress, difficult relationships, transitions, and recurring patterns that keep life feeling smaller than it could be. My practice is informed by evidence-based approaches and shaped around practical goals you set together with me.</p>
            <p>I hold training in cognitive-behavioral and relational methods, with ongoing consultation and a focus on measurable, sustained change. My work is collaborative: I bring structure, and you bring the expert knowledge of your life.</p>
            <p class="muted">Sessions are offered through a membership model that supports continuous work over time rather than one-off fixes.</p>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </section>

        <aside class="panel">
          <h3 style="margin-top:0">Practical details</h3>
          <div class="details">
            <div><strong>Location:</strong> {{CITY}}, {{STATE}}</div>
            <div style="margin-top:6px"><strong>Contact:</strong> <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
            <div style="margin-top:6px"><strong>Email:</strong> <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
          </div>

          <div class="fineprint">
            <strong>Confidentiality</strong>
            <p class="muted">Conversations here are confidential within legal and ethical limits. I will explain limits to confidentiality (for example, safety concerns or court-ordered disclosures) before we begin work.</p>
            <strong>Scope & crisis</strong>
            <p class="muted">I provide outpatient psychotherapy and not emergency services. If you are in immediate danger or are experiencing a life-threatening emergency, call local emergency services or go to the nearest emergency department.</p>
          </div>
        </aside>
      </div>

      <section style="margin-top:18px" class="panel">
        <h3 style="margin-top:0">How the membership is framed</h3>
        <p class="muted">Rather than hourly sessions only, the membership is a steady framework: an agreed-upon rhythm of sessions, brief check-ins, and a modest reserve of focused work time each month for planning and specific interventions. This helps keep momentum between sessions without pressure to ‘fix’ everything immediately.</p>
        <p style="margin-top:10px">If you'd like a quick sense of what a few months of work might look like, I invite you to book an introductory conversation. We’ll outline goals and a simple plan you can take away, no pressure.</p>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">Schedule an introductory conversation</a>
      </section>

      <footer>
        <div class="muted">Licensed clinician. Telehealth and limited in-person availability. For questions about accessibility or accommodations, contact <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</div>
      </footer>
    </main>
  </div>
</body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Focus Areas — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f9fbfb;--accent:#2c5d5d;--muted:#627173;--card:#ffffff}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;background:#f9fbfb;color:#142424}
    .wrap{max-width:980px;margin:30px auto;padding:24px;background:var(--card);border-radius:12px;box-shadow:0 8px 30px rgba(20,30,30,0.05)}
    header{display:flex;justify-content:space-between;align-items:center}
    header h1{margin:0;font-size:18px;color:var(--accent)}
    nav a{margin-left:12px;color:var(--accent);text-decoration:none}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:20px}
    .list{display:flex;flex-direction:column;gap:12px}
    .card{padding:14px;border-radius:8px;background:linear-gradient(180deg,#fff,#fbffff);border:1px solid #eef6f6}
    .card h3{margin:0 0 6px}
    .pale{color:var(--muted);font-size:14px}
    .cta{display:inline-block;margin-top:10px;background:var(--accent);color:#fff;padding:9px 12px;border-radius:8px;text-decoration:none}
    .wizard{margin-top:12px}
    label{display:block;font-size:13px;margin-top:10px}
    input[type="text"], select, textarea{width:100%;padding:8px;border-radius:6px;border:1px solid #d7e7e7;margin-top:6px}
    button{background:#2c5d5d;color:#fff;padding:8px 10px;border:0;border-radius:6px;margin-top:10px;cursor:pointer}
    .output{white-space:pre-wrap;background:#f3faf9;border:1px dashed #d8efee;padding:10px;border-radius:6px;margin-top:10px}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div>
        <h1>{{BUSINESS_NAME}} — Areas of focus</h1>
        <div class="pale">Evidence-informed care for adults navigating common life challenges</div>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="about.html">About</a>
        <a href="specialties.html">Focus</a>
        <a href="approach.html">My Approach</a>
      </nav>
    </header>

    <div class="grid">
      <section>
        <div class="list">
          <div class="card">
            <h3>Transition & adjustment</h3>
            <div class="pale">Work around career moves, life-stage changes, returning to work, or relocating — with practical coping strategies and planning.</div>
          </div>

          <div class="card">
            <h3>Relationship patterns</h3>
            <div class="pale">Explore recurring dynamics in attachment, communication, and boundaries to shift how connections feel day-to-day.</div>
          </div>

          <div class="card">
            <h3>Persistent worry & low energy</h3>
            <div class="pale">Tools for managing chronic worry, low mood, and concentration concerns that interfere with functioning.</div>
          </div>

          <div class="card">
            <h3>Parenting stress & role demands</h3>
            <div class="pale">Support in making space for self-care, planning around family responsibilities, and building sustainable routines.</div>
          </div>

          <div class="card">
            <h3>Performance anxiety & self-expectations</h3>
            <div class="pale">Practical ways to adjust high self-expectations and reduce anxiety that looks like perfectionism or burnout.</div>
          </div>
        </div>
      </section>

      <aside>
        <div class="card">
          <h3 style="margin-top:0">A brief self-check</h3>
          <div class="pale">Try this short non-diagnostic intake to gather notes for an initial meeting. It helps you notice patterns and come prepared with questions.</div>

          <div class="wizard" id="wizard1">
            <div id="step1">
              <label for="concern">What brings you in right now? (2–3 short sentences)</label>
              <textarea id="concern" rows="3"></textarea>
              <button id="toStep2">Next</button>
            </div>

            <div id="step2" style="display:none">
              <label for="triggers">Are there common triggers or situations when you notice this most?</label>
              <input id="triggers" type="text" placeholder="e.g., evenings, work meetings, parenting moments">
              <label for="strengths">What helps you cope even a little? (people, activities, routines)</label>
              <input id="strengths" type="text" placeholder="e.g., walking, a friend, a morning routine">
              <button id="toStep3">Next</button>
            </div>

            <div id="step3" style="display:none">
              <label for="goal">What would you hope is different in three months?</label>
              <input id="goal" type="text" placeholder="A small, realistic change">
              <button id="buildQuestions">Create questions to bring to a consultation</button>
            </div>

            <div id="result" style="display:none">
              <div class="output" id="questionsOutput"></div>
              <button id="copyQuestions">Copy questions</button>
              <button id="restartWizard">Start over</button>
            </div>
          </div>

          <script>
            (function(){
              var step1 = document.getElementById('step1');
              var step2 = document.getElementById('step2');
              var step3 = document.getElementById('step3');
              var result = document.getElementById('result');
              document.getElementById('toStep2').addEventListener('click',function(){
                if(document.getElementById('concern').value.trim()===''){alert('A short note helps.');return}
                step1.style.display='none';step2.style.display='block';
              });
              document.getElementById('toStep3').addEventListener('click',function(){
                step2.style.display='none';step3.style.display='block';
              });
              document.getElementById('buildQuestions').addEventListener('click',function(){
                var c=document.getElementById('concern').value.trim();
                var t=document.getElementById('triggers').value.trim();
                var s=document.getElementById('strengths').value.trim();
                var g=document.getElementById('goal').value.trim();
                var lines=[];
                lines.push('Notes to bring to a consultation:');
                lines.push('• Presenting concern: '+(c||'—'));
                lines.push('• Typical triggers/situations: '+(t||'—'));
                lines.push('• What helps at the moment: '+(s||'—'));
                lines.push('• Short goal (3 months): '+(g||'—'));
                lines.push('\nSuggested questions to ask in an initial meeting:');
                lines.push('1) Given these concerns, what would a first 3-session focus look like?');
                lines.push('2) Which practical skills or strategies might be useful early on?');
                lines.push('3) What would you recommend for measuring small gains between sessions?');
                var out=lines.join('\n');
                document.getElementById('questionsOutput').textContent=out;
                step3.style.display='none';result.style.display='block';
              });
              document.getElementById('copyQuestions').addEventListener('click',function(){
                var t=document.getElementById('questionsOutput').textContent;navigator.clipboard&&navigator.clipboard.writeText(t).then(function(){alert('Copied to clipboard')},function(){alert('Copy failed')});
              });
              document.getElementById('restartWizard').addEventListener('click',function(){
                document.getElementById('concern').value='';document.getElementById('triggers').value='';document.getElementById('strengths').value='';document.getElementById('goal').value='';result.style.display='none';step1.style.display='block';
              });
            })();
          </script>

        </div>

        <div style="margin-top:12px" class="pale">This is not a diagnosis or a substitute for clinical assessment. It’s a structured way to notice patterns and prepare for a conversation.</div>
      </aside>
    </div>

  </div>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>My Approach — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f2f6f6;--accent:#254c4c;--muted:#5f6d6d}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#0f2a2a}
    .shell{max-width:980px;margin:32px auto;padding:26px;background:#fff;border-radius:12px;box-shadow:0 12px 40px rgba(18,30,30,0.06)}
    header{display:flex;justify-content:space-between;align-items:center}
    h1{margin:0;color:var(--accent);font-size:18px}
    nav a{margin-left:12px;color:var(--accent);text-decoration:none}
    .columns{display:grid;grid-template-columns:1fr 380px;gap:20px;margin-top:18px}
    .section{padding:14px;border-radius:10px;background:linear-gradient(180deg,#fff,#fbffff)}
    .lead{color:var(--muted);line-height:1.5}
    .planner{margin-top:10px}
    label{display:block;font-size:13px;margin-top:8px}
    select,input[type="number"],input[type="text"]{width:100%;padding:8px;border-radius:6px;border:1px solid #e1efef}
    textarea{width:100%;padding:8px;border-radius:6px;border:1px solid #e1efef}
    .btn{margin-top:10px;padding:9px 12px;border-radius:8px;border:0;background:var(--accent);color:#fff;cursor:pointer}
    .summary{margin-top:10px;background:#f7fffe;border-radius:8px;padding:10px;border:1px dashed #d7efee;white-space:pre-wrap}
    .note{font-size:13px;color:var(--muted);margin-top:10px}
  </style>
</head>
<body>
  <div class="shell">
    <header>
      <div>
        <h1>{{BUSINESS_NAME}} — My approach</h1>
        <div class="lead">A practical, collaborative framework: small, testable changes that fit your life and priorities.</div>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="about.html">About</a>
        <a href="specialties.html">Focus</a>
        <a href="approach.html">My Approach</a>
      </nav>
    </header>

    <div class="columns">
      <main>
        <section class="section">
          <h2 style="margin-top:0">The work, in plain terms</h2>
          <p class="lead">I view therapy like a workbench: we set a small number of measurable projects, try interventions that look feasible for your week-to-week life, and check what helps. The process is collaborative and paced to what you can realistically maintain.</p>

          <h3 style="margin-top:14px">What to expect in the first month</h3>
          <ul class="lead">
            <li>One intake to map immediate concerns and practical barriers.</li>
            <li>Two-to-three focused sessions to try a strategy and refine it.</li>
            <li>Short, agreed-upon steps between sessions (experiments, scheduling, brief exercises).</li>
          </ul>

          <div class="note">This is outpatient psychotherapy and not an emergency service. If you are in immediate danger, please contact local emergency services. Confidentiality is maintained within legal and ethical limits; I will review these limits with you.</div>
        </section>

        <section class="section" style="margin-top:14px">
          <h3 style="margin-top:0">Self-screening intake — exploratory version</h3>
          <p class="lead">A different intake wizard to highlight situations, supports, and practical questions you may want to bring to an initial visit.</p>

          <div id="wizard2">
            <label for="situation">Briefly, describe a recent situation that felt difficult</label>
            <textarea id="situation" rows="3"></textarea>

            <label for="frequency">How often does this happen?</label>
            <select id="frequency"><option>Daily</option><option>Several times a week</option><option>Weekly</option><option>Less often</option></select>

            <label for="impact">What area of life is most affected?</label>
            <select id="impact"><option>Work/study</option><option>Relationships</option><option>Sleep/energy</option><option>Other</option></select>

            <button class="btn" id="createBringList">Generate a bring-list</button>

            <div id="bringOutput" class="summary" style="display:none"></div>
            <button id="copyBring" class="btn" style="display:none;background:#3b6b6b">Copy to clipboard</button>
          </div>

          <script>
            (function(){
              document.getElementById('createBringList').addEventListener('click',function(){
                var s=document.getElementById('situation').value.trim();
                var f=document.getElementById('frequency').value;
                var i=document.getElementById('impact').value;
                if(!s){alert('A short example helps us make useful questions.');return}
                var lines=[];
                lines.push('Bring-list for an initial meeting:');
                lines.push('- Short description: '+s);
                lines.push('- Frequency: '+f);
                lines.push('- Area affected: '+i);
                lines.push('\nQuestions you might ask:');
                lines.push('• What pattern of steps would you suggest for the first 4 weeks?');
                lines.push('• What practical skills or routines could fit my current schedule?');
                lines.push('• How will we notice small improvement?');
                var out=lines.join('\n');
                var el=document.getElementById('bringOutput');el.textContent=out;el.style.display='block';
                document.getElementById('copyBring').style.display='inline-block';
              });
              document.getElementById('copyBring').addEventListener('click',function(){
                var t=document.getElementById('bringOutput').textContent;navigator.clipboard&&navigator.clipboard.writeText(t).then(function(){alert('Copied')},function(){alert('Copy failed')});
              });
            })();
          </script>

        </section>
      </main>

      <aside>
        <section class="section">
          <h3 style="margin-top:0">Session Planner</h3>
          <p class="lead">Quickly sketch a small plan that fits your time and goals. You can copy a plaintext summary to bring to our first call.</p>

          <div class="planner">
            <label for="goalText">Primary goal (one short sentence)</label>
            <input id="goalText" type="text" placeholder="e.g., reduce evening worry to sleep better">

            <label for="frequencyChoice">Session rhythm</label>
            <select id="frequencyChoice"><option>Weekly</option><option>Every other week</option><option>Monthly check-in</option></select>

            <label for="sessionFocus">Early session focus</label>
            <select id="sessionFocus"><option>Skill building (practical strategies)</option><option>Relationships & boundaries</option><option>Behavioral activation & routines</option><option>Short-term planning for transitions</option></select>

            <label for="timeAvailable">Weekly time you can commit</label>
            <input id="timeAvailable" type="text" placeholder="e.g., 45 minutes, or two 20-minute check-ins">

            <button class="btn" id="buildPlan">Build my plan</button>

            <div id="planSummary" class="summary" style="display:none"></div>
            <button id="copyPlan" class="btn" style="display:none;background:#3b6b6b">Copy plan</button>
          </div>

          <script>
            (function(){
              function safe(v){return (v||'—')}
              document.getElementById('buildPlan').addEventListener('click',function(){
                var goal=document.getElementById('goalText').value.trim();
                var freq=document.getElementById('frequencyChoice').value;
                var focus=document.getElementById('sessionFocus').value;
                var time=document.getElementById('timeAvailable').value.trim();
                if(!goal){alert('A short goal helps make a clearer plan.');return}
                var lines=[];
                lines.push('Personal session plan');
                lines.push('Goal: '+safe(goal));
                lines.push('Planned rhythm: '+safe(freq));
                lines.push('Early focus: '+safe(focus));
                lines.push('Weekly time available: '+safe(time));
                lines.push('\nSuggested first steps:');
                lines.push('1) Intake & problem mapping (one session) — identify 2 concrete targets.');
                lines.push('2) Skill-focused work (1–3 sessions) — brief exercises tailored to your week.');
                lines.push('3) Check-in and adjust (ongoing) — short review of what changed and next priorities.');
                var out=lines.join('\n');
                var el=document.getElementById('planSummary');el.textContent=out;el.style.display='block';
                document.getElementById('copyPlan').style.display='inline-block';
              });
              document.getElementById('copyPlan').addEventListener('click',function(){
                var t=document.getElementById('planSummary').textContent;navigator.clipboard&&navigator.clipboard.writeText(t).then(function(){alert('Plan copied')},function(){alert('Copy failed')});
              });
            })();
          </script>

          <div class="note">If you have questions about whether this approach fits your needs, call or email to arrange a short consultation. For urgent safety concerns, contact emergency services.</div>

        </section>
      </aside>
    </div>

    <footer style="margin-top:18px;color:var(--muted)">
      <div>For questions about access, sliding scale options, or paperwork, reach out at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</div>
    </footer>
  </div>
</body>
</html>"} 
